import java.util.*;

class Solution {
    public List<List<Integer>> matrixBlockSum(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] P = new int[m + 1][n + 1]; // P[i][j] = sum of grid[0..i-1][0..j-1]
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i + 1][j + 1] = grid[i][j] + P[i][j + 1] + P[i + 1][j] - P[i][j];
        List<List<Integer>> res = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            List<Integer> row = new ArrayList<>();
            int r1 = Math.max(0, r - k), r2 = Math.min(m - 1, r + k);
            for (int c = 0; c < n; c++) {
                int c1 = Math.max(0, c - k), c2 = Math.min(n - 1, c + k);
                row.add(P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1]);
            }
            res.add(row);
        }
        return res;
    }
}

