function matrixBlockSum(g, k) {
  const m = g.length, n = g[0].length;
  return g.map((row, r) => row.map((_, c) => { let s = 0; for (let i = Math.max(0, r - k); i <= Math.min(m - 1, r + k); i++) for (let j = Math.max(0, c - k); j <= Math.min(n - 1, c + k); j++) s += g[i][j]; return s; }));
}
